#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <ctype.h>

#define MAX_LOG_LINE 512
#define MAX_USERNAME 64
#define MAX_ACTION 128

typedef struct {
    int verbose_logging;
    int audit_mode;
    int sanitize_inputs;
    int encode_outputs;
} FeatureFlags;

static FeatureFlags g_flags = {0};

void load_feature_flags(const char *config_path) {
    FILE *f = fopen(config_path, "r");
    if (!f) {
        g_flags.verbose_logging = 0;
        g_flags.audit_mode = 1;
        g_flags.sanitize_inputs = 1;
        g_flags.encode_outputs = 1;
        return;
    }
    char line[256];
    while (fgets(line, sizeof(line), f)) {
        if (strncmp(line, "verbose_logging=", 16) == 0)
            g_flags.verbose_logging = atoi(line + 16);
        else if (strncmp(line, "audit_mode=", 11) == 0)
            g_flags.audit_mode = atoi(line + 11);
        else if (strncmp(line, "sanitize_inputs=", 16) == 0)
            g_flags.sanitize_inputs = atoi(line + 16);
        else if (strncmp(line, "encode_outputs=", 15) == 0)
            g_flags.encode_outputs = atoi(line + 15);
    }
    fclose(f);
}

static int sanitize_log_field(const char *input, char *output, size_t outlen) {
    size_t i, j = 0;
    for (i = 0; input[i] && j < outlen - 1; i++) {
        if (input[i] == '\n' || input[i] == '\r') {
            if (j + 4 >= outlen - 1) break;
            output[j++] = '\\'; output[j++] = 'n';
        } else if (input[i] == '\t') {
            if (j + 4 >= outlen - 1) break;
            output[j++] = '\\'; output[j++] = 't';
        } else {
            output[j++] = input[i];
        }
    }
    output[j] = '\0';
    return 0;
}

static int validate_username(const char *username) {
    if (!username || strlen(username) == 0 || strlen(username) >= MAX_USERNAME)
        return -1;
    for (size_t i = 0; username[i]; i++) {
        if (!isalnum((unsigned char)username[i]) && username[i] != '_' && username[i] != '-')
            return -1;
    }
    return 0;
}

static void write_audit_log(const char *logfile, const char *timestamp,
                            const char *username, const char *action,
                            const char *detail) {
    FILE *lf = fopen(logfile, "a");
    if (!lf) return;
    fprintf(lf, "[%s] user=%s action=%s detail=%s\n",
            timestamp, username, action, detail);
    fclose(lf);
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", tm_info);
}

void handle_request(const char *username, const char *action, const char *client_detail) {
    char ts[64];
    get_timestamp(ts, sizeof(ts));

    char safe_user[MAX_USERNAME * 2];
    char safe_action[MAX_ACTION * 2];
    char safe_detail[MAX_LOG_LINE];

    if (g_flags.sanitize_inputs) {
        if (validate_username(username) != 0) {
            username = "INVALID_USER";
        }
    }

    if (g_flags.encode_outputs) {
        sanitize_log_field(username, safe_user, sizeof(safe_user));
        sanitize_log_field(action, safe_action, sizeof(safe_action));
        sanitize_log_field(client_detail, safe_detail, sizeof(safe_detail));
    } else {
        strncpy(safe_user, username, sizeof(safe_user) - 1);
        safe_user[sizeof(safe_user) - 1] = '\0';
        strncpy(safe_action, action, sizeof(safe_action) - 1);
        safe_action[sizeof(safe_action) - 1] = '\0';
        strncpy(safe_detail, client_detail, sizeof(safe_detail) - 1);
        safe_detail[sizeof(safe_detail) - 1] = '\0';
    }

    if (g_flags.audit_mode) {
        write_audit_log("/var/log/app/audit.log", ts, safe_user, safe_action, safe_detail);
    }

    if (g_flags.verbose_logging) {
        char verbose_line[MAX_LOG_LINE * 2];
        snprintf(verbose_line, sizeof(verbose_line),
                 "[VERBOSE][%s] Processing request from '%s': %s (%s)",
                 ts, username, action, client_detail);
        FILE *vf = fopen("/var/log/app/verbose.log", "a");
        if (vf) {
            fprintf(vf, "%s\n", verbose_line);
            fclose(vf);
        }
    }
}

int main(int argc, char *argv[]) {
    load_feature_flags("/etc/app/features.conf");

    const char *user = getenv("HTTP_X_USER");
    const char *action = getenv("HTTP_X_ACTION");
    const char *detail = getenv("HTTP_X_DETAIL");

    if (!user) user = "anonymous";
    if (!action) action = "unknown";
    if (!detail) detail = "";

    handle_request(user, action, detail);

    printf("Content-Type: text/plain\r\n\r\nOK\n");
    return 0;
}
